"\"\"\"E2 — Distillation : des élèves (LoRA, générateur jacobien, ablation, hypernetwork, ALBERT)\napprennent d'un professeur DONT les W1 sont un vrai champ de jacobiennes.\n\nCLI : python e2_distill.py --parent gauss|mlp --method gen|genfree|lora|hyp|albert|dense\n      --seed 0 [--steps N]\n\nPerte élève : KL(PT ‖ PS) sur les lots de la tâche A (mêmes lots pour toutes les méthodes,\ngraine appariée). Le professeur est construit par parent.build_parent(kind, seed) : ses W1 sont\nfigées aux tranches jacobiennes, ses autres paramètres sont entraînés sur la tâche A.\n\nMesures : courbe KL (efficacité d'échantillons), KL final, CE de l'élève sur le vrai corpus,\ndistance des W1 de l'élève aux W1 du professeur.\n\"\"\"\nimport argparse\nimport json\nimport sys\nimport time\nfrom pathlib import Path\n\nimport numpy as np\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\nfrom phase3_model import Transformer\nfrom phase3_methods import make_provider\nfrom phase3_corpus import get_task\nfrom distill_model import DistillTransformer, cosine_lr\nimport parent as P\n\nROOT = Path(__file__).resolve().parents[1]\nD, D_FF, L, H = P.D, P.D_FF, P.L, P.H\nT, B = P.T, P.B\nSTEPS = 1000\nEVAL_EVERY = 100\nCHECKPOINTS = {1, 50, 100, 200, 300, 400, 600, 800, 1000}\n\n\ndef run(kind, method, seed, steps=STEPS):\n    t0 = time.time()\n    par = P.build_parent(kind, seed)\n    teacher = Transformer(par[\"V\"], D, D_FF, L, H, T, np.random.default_rng(1))\n    teacher.params = par[\"parent_params\"]\n    W1s_teacher = par[\"field\"][\"Ws\"]\n\n    train, val = get_task(\"a\", seed=0)\n    Xval = val.eval_windows(T, 64)\n    # PT figé sur les fenêtres de validation (évaluation)\n    PTval = np.concatenate([teacher.forward(Xval[i:i + 32], W1s_teacher)[1][\"Pp\"]\n                            for i in range(0, 64, 32)])\n\n    rng = np.random.default_rng(1000 + seed)      # init modèle puis fournisseur\n    brng = np.random.default_rng(50000 + seed)     # lots — identiques pour toutes les méthodes\n    student = DistillTransformer(train.V, D, D_FF, L, H, T, rng)\n    prov = make_provider(method, D, D_FF, L, rng, K=6, r=2, e_dim=8, Hh=6)\n\n    curve = []\n    for step in range(steps):\n        X = train.sample_batch(B, T, brng)\n        loss_t, c_t = teacher.forward(X, W1s_teacher)\n        PT = c_t[\"Pp\"]\n        W1s = prov.W_layers()\n        loss, cache = student.forward_distill(X, W1s, PT)\n        grads, Gs = student.backward(cache, W1s)\n        prov.backprop(Gs)\n        lr = cosine_lr(step, steps)\n        student.step(grads, lr)\n        prov.step(lr)\n        if (step + 1) in CHECKPOINTS:\n            W1s = prov.W_layers()\n            kl = student.eval_distill(Xval, W1s, PTval)\n            ce = student.eval_ce(Xval, W1s)\n            curve.append({\"step\": step + 1, \"train_kl\": loss, \"val_kl\": kl, \"val_ce\": ce})\n            print(f\"  s{seed}/{method}/{kind} step {step+1}: KL={kl:.4f} CE={ce:.4f}\", flush=True)\n\n    W1s = prov.W_layers()\n    dist_to_parent = [float(np.linalg.norm(W1s[l] - W1s_teacher[l]) / np.linalg.norm(W1s_teacher[l]))\n                      for l in range(L)]\n    res = {\n        \"parent\": kind, \"method\": method, \"seed\": seed, \"steps\": steps,\n        \"parent_val\": par[\"parent_val\"], \"ff1_params\": prov.n_params,\n        \"final_kl\": curve[-1][\"val_kl\"], \"final_ce\": curve[-1][\"val_ce\"],\n        \"kl_100\": next(c[\"val_kl\"] for c in curve if c[\"step\"] == 100),\n        \"kl_300\": next(c[\"val_kl\"] for c in curve if c[\"step\"] == 300),\n        \"dist_to_parent_W1\": dist_to_parent, \"curve\": curve,\n        \"time_s\": round(time.time() - t0, 1),\n    }\n    out = ROOT / \"results\" / \"e2_distill\"\n    out.mkdir(parents=True, exist_ok=True)\n    (out / f\"{kind}_{method}_s{seed}.json\").write_text(json.dumps(res))\n    print(f\"[done] {kind}/{method}/s{seed}: KL={res['final_kl']:.4f} CE={res['final_ce']:.4f} \"\n          f\"parentCE={res['parent_val']:.4f} ({res['time_s']}s, ff1={prov.n_params})\", flush=True)\n    return res\n\n\nif __name__ == \"__main__\":\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--parent\", choices=[\"gauss\", \"mlp\"], required=True)\n    ap.add_argument(\"--method\", choices=[\"gen\", \"genfree\", \"lora\", \"hyp\", \"albert\", \"dense\"], required=True)\n    ap.add_argument(\"--seed\", type=int, default=0)\n    ap.add_argument(\"--steps\", type=int, default=STEPS)\n    a = ap.parse_args()\n    run(a.parent, a.method, a.seed, a.steps)\n"